2.1 Parties
Party preference profiles (ten ALCL survey items) can be derived from the candidates and from the citizens which reposndet in the survey.


Code
parties_cand &lt;- cand |&gt;
  mutate(
    party_full = party,
    party = party_full |&gt;
      fct_relevel(sort(levels(party_full))) |&gt;
      fct_lump_min(6, other_level = "Other Party") |&gt;
      fct_other(
        drop = "N. Nej til privatisering af kommunale veje",
        other_level = "Other Party"
      ) |&gt;
      fct_relevel("Other Party", after = Inf)
  ) |&gt;
  pivot_longer(
    cols = paste0("Q", 1:26),
    names_to = "Name",
    values_to = "Preference"
  ) |&gt;
  left_join(crosswalk, by = c("Name" = "Q")) |&gt;
  filter_out(is.na(ALCL)) |&gt;
  summarize(
    Mean = mean(Preference, na.rm = TRUE),
    SD = sd(Preference, na.rm = TRUE),
    N_cand = n(),
    .by = c(party, ALCL)
  ) |&gt;
  left_join(
    loc_domains_questions |&gt; select(Label, Preference_s),
    by = c("ALCL" = "Label")
  ) |&gt;
  rename(Description = Preference_s) |&gt;
  mutate(ALCL = factor(ALCL, levels = paste0("ALCL", 1:10))) |&gt;
  arrange(party, ALCL)
parties_cand |&gt;
  select(party, ALCL, Description, Mean, N_cand) |&gt;
  pivot_wider(
    names_from = c(ALCL, Description),
    values_from = c(Mean),
    names_sep = "&lt;br&gt;"
  ) |&gt;
  gt() |&gt;
  tab_header(
    title = "Local party profiles based on candidate preferences"
  ) |&gt;
  cols_label(
    party = "Party",
    N_cand = "Candidates"
  ) |&gt;
  cols_label_with(starts_with("ALCL"), md) |&gt;
  fmt_number(columns = everything(), decimals = 2) |&gt;
  fmt_number(columns = c(N_cand), decimals = 0) |&gt;
  data_color(
    columns = starts_with("ALCL"),
    palette = "RdBu",
    method = "numeric",
    domain = c(-2, 2)
  ) |&gt;
  cols_width(
    party ~ px(200),
    N_cand ~ px(100),
    starts_with("ALCL") ~ px(85)
  ) |&gt;
  tab_footnote(
    "Only parties with at least six candidates and more than 2% respondents in the people survey are included."
  ) |&gt;
  opt_interactive(use_pagination = FALSE)




